    if (e === null) {
        return undefined;
    }
    if ((e[2] !== undefined) && !goChan3H29G16IntIndex (masked, fn, start, e[2])) {
        return undefined;
    }
    const ind = d[1];
    const x = d[2];
    const guard = (e[2] === undefined) ? (k + ' < len(' + v + ')') : (k + ' >= 0 && ' + k + ' < len(' + v + ')');
    return { 'start': ls, 'end': le, 'text': ind + 'var ' + x + ' ' + type + '\n' + ind + 'if ' + guard + ' {\n' + ind + '\t' + x + ' = ' + v + '[' + k + ']\n' + ind + '}' };
