// base methods whose every return path is already a MarketTyped/CurrencyTyped row, so a
// second wrapper around their call is the identity (the helper hands back the same map for a plain row).
const GO_PLAIN_ROW_METHODS = [ 'Market', 'SafeMarket', 'Currency', 'SafeCurrency' ];
const GO_PLAIN_ROW_CALL = new RegExp ('^(?:this\\.(?:DerivedExchange\\.|Exchange\\.)(?:' + GO_PLAIN_ROW_METHODS.join ('|')
    + ')|this\\.(?:SafeCurrencyStructure|SafeMarketStructure))\\(');  // the two structure builders have no venue override

function dropNoOpMapTyped (content: string): string {
    const callee = new RegExp ('^(?:this\\.(?:DerivedExchange\\.|Exchange\\.)?(?:' + GO_MAP_RETURNING_METHODS.join ('|') + ')|(?:ccxt\\.)?(?:' + GO_PROVEN_STRUCT_TO_MAP_CALLS.join ('|') + '))\\(');
    let out = '';
    let cursor = 0;
    const wrapper = /\b(?:ccxt\.)?(?:MapTyped|MarketTyped|CurrencyTyped)\(|\bthis\.(?:DerivedExchange\.|Exchange\.)?(?:Currency|SafeCurrency|SafeMarket)\(/g;
    for (let m = wrapper.exec (content); m !== null; m = wrapper.exec (content)) {
        if (m.index < cursor) {
            continue;
        }
        const open = m.index + m[0].length - 1;
        const end = goMatchingCloseText (content, open, '()');
        if (end < 0) {
            continue;
        }
        if (m[0].startsWith ('this.')) {
            if (content.startsWith ('.(map[string]any)', end + 1)) {
                out += content.substring (cursor, end + 1);
                cursor = end + 1 + '.(map[string]any)'.length;
            }
            continue;
        }
        const inner = content.substring (open + 1, end);
        const innerOpen = inner.indexOf ('(');
        // a MarketTyped/CurrencyTyped wrap is the identity only on a base method that already answers a
        // plain row; MapTyped keeps its wider table
        const rowWrap = /^(?:ccxt\.)?(?:MarketTyped|CurrencyTyped)\($/.test (m[0]);
        const innerIsCall = (rowWrap ? GO_PLAIN_ROW_CALL : callee).test (inner);
        if (!innerIsCall || (goMatchingCloseText (inner, innerOpen, '()') !== inner.length - 1)) {
            continue;
        }
        out += content.substring (cursor, m.index) + dropNoOpMapTyped (inner);
        cursor = end + 1;
        wrapper.lastIndex = cursor;
    }
    return out + content.substring (cursor);
}

// ------------------------------------------------------------------------------------
// gofmt's block, blank-line and table rules
// ------------------------------------------------------------------------------------
// A pass that splices statement text cannot keep gofmt's layout: it puts a body on the
// control line, leaves a second blank line behind, or writes literal entries unaligned.
// These rules run once on the finished file, per file (not per splice).
type GoCompositeEntryAligner = { 'alignGoCompositeEntries': (entries: string[]) => string[] };

// same as goTextMaskLiteralsAndComments but the comments stay readable: the layout rules below
// have to see a trailing `//` (it takes the line out of every rule) while a `//` inside a
// string literal must not count
function goTextMaskLiteralsOnly (content: string): string {
    const out = content.split ('');
    let state = 'code';
    let escaped = false;
    for (let i = 0; i < content.length; i++) {
        const c = content[i];
        if (state === 'code') {
            if (c === '"') { state = 'dq'; out[i] = ' '; continue; }
            if (c === '`') { state = 'raw'; out[i] = ' '; continue; }
            if (c === '\'') { state = 'rune'; out[i] = ' '; continue; }
            continue;
        }
        if (c !== '\n') {
            out[i] = ' ';
        }
        if (state === 'dq') { if (escaped) { escaped = false; } else if (c === '\\') { escaped = true; } else if (c === '"') { state = 'code'; } continue; }
        if (state === 'rune') { if (escaped) { escaped = false; } else if (c === '\\') { escaped = true; } else if (c === '\'') { state = 'code'; } continue; }
        if (state === 'raw') { if (c === '`') { state = 'code'; } continue; }
    }
    return out.join ('');
}

// one flag per line: it starts outside a raw string and a block comment, so the layout rules may
// rewrite it (a quote or a comment keeps its own spacing in the source)
function goTextCodeLineStarts (content: string): boolean[] {
    const starts: boolean[] = [ true ];
    let state = 'code';
    for (let i = 0; i < content.length; i++) {
        const c = content[i];
        if (state === 'code') {
            if ((c === '/') && (content[i + 1] === '/')) { state = 'line'; i++; continue; }
            if ((c === '/') && (content[i + 1] === '*')) { state = 'block'; i++; continue; }
            if (c === '"') { state = 'dq'; continue; }
            if (c === '`') { state = 'raw'; continue; }
            if (c === '\'') { state = 'rune'; continue; }
            if (c === '\n') { starts.push (true); }
            continue;
        }
        if (c === '\n') {
            if (state === 'line') { state = 'code'; }
            starts.push (state === 'code');
            continue;
        }
        if (state === 'line') { continue; }
        if (state === 'block') { if ((c === '*') && (content[i + 1] === '/')) { state = 'code'; i++; } continue; }
        if (state === 'dq') { if (c === '\\') { i++; } else if (c === '"') { state = 'code'; } continue; }
        if (state === 'rune') { if (c === '\\') { i++; } else if (c === '\'') { state = 'code'; } continue; }
        if (state === 'raw') { if (c === '`') { state = 'code'; } continue; }
    }
    return starts;
}

// gofmt always breaks a block: `if x { y }` comes back as three lines. The body is split into
// statements only when it holds one, and a nested block is broken too.
function goGofmtExpandBlockLine (line: string, code: string, commentFree: string): string[] | null {
    if (!/^\t*(?:if|for|switch|select)\b/.test (code) || (commentFree.indexOf ('//') >= 0)) {
        return null;
    }
    const open = code.indexOf ('{');
    const trimmed = code.trimEnd ();
    if ((open < 0) || !trimmed.endsWith ('}')) {
        return null;
    }
    const maskedBody = code.slice (open + 1, trimmed.length - 1);
    let level = 0;
    for (let i = 0; i < maskedBody.length; i++) {
        const c = maskedBody[i];
        if (c === '{') { level += 1; } else if (c === '}') { level -= 1; }
        if ((level < 0) || (maskedBody.indexOf (';') >= 0)) {
            return null;
        }
    }
    if (level !== 0) {
        return null;
    }
    const indent = /^\t*/.exec (line)![0];
    const head = line.slice (indent.length, open).trimEnd ();
    const body = line.slice (open + 1, line.trimEnd ().length - 1).trim ();
    if ((body.length === 0) || (head.length === 0)) {
        return null;
    }
    const inner = goGofmtExpandBlockLine (indent + '\t' + body, '\t' + body, goTextMaskLiteralsOnly (body));
    if (inner !== null) {
        return [ indent + head + ' {', ...inner, indent + '}' ];
    }
    return [ indent + head + ' {', indent + '\t' + body, indent + '}' ];
}

// gofmt puts a keyed literal's entries one tab inside its opening line, their values in one
// column and the closing brace on the opening line's indent; only a literal whose body is all
// single-line keyed entries is rewritten, so anything else keeps the printer's text.
function goGofmtAlignTables (content: string, aligner: GoCompositeEntryAligner): string {
    const lines = content.split ('\n');
    const live = goTextCodeLineStarts (content);
    const depth = (l: string) => /^\t*/.exec (l)![0].length;
    const keyed = /^(\t*)"((?:[^"\\]|\\.)*)": (.*?)(,?)$/;
    for (let i = 0; i < lines.length; i++) {
        if (!live[i] || !lines[i].trimEnd ().endsWith ('{')) {
            continue;
        }
        const ind = depth (lines[i]);
        const entries: string[] = [];
        let j = i + 1;
        let bad = false;
        while ((j < lines.length) && !((depth (lines[j]) <= ind) && /^\t*\}/.test (lines[j]))) {
            if (!live[j] || (lines[j].trim ().length === 0) || !keyed.test (lines[j]) || (depth (lines[j]) > ind + 1)) {
                bad = true;
                break;
            }
            entries.push (lines[j]);
            j += 1;
        }
        if (bad || (j >= lines.length) || (entries.length === 0)) {
            continue;
        }
        const close = lines[j].replace (/^\t*/, '');
        if (!/^\}[)\]\s,]*$/.test (close)) {
            continue;
        }
        const texts: string[] = [];
        let usable = true;
        for (const entry of entries) {
            const m = keyed.exec (entry)!;
            const mask = goTextMaskLiteralsAndComments (m[3]);
            const value = m[3].replace (/^ +/, '');
            // a nested literal, an unbalanced bracket, a second entry on the line or a trailing
            // comment ends gofmt's alignment section: leave that literal to the printer
            if ((value.length === 0) || /[{}]/.test (mask) || (mask.split ('[').length !== mask.split (']').length) || (m[3].indexOf ('": ') >= 0) || (goTextMaskLiteralsOnly (entry).indexOf ('//') >= 0)) {
                usable = false;
                break;
            }
            texts.push ('\t'.repeat (ind + 1) + '"' + m[2] + '": ' + value);
        }
        if (!usable) {
            continue;
        }
        const aligned = aligner.alignGoCompositeEntries (texts);
        if (aligned.length !== entries.length) {
            continue;
        }
        for (let k = 0; k < entries.length; k++) {
            lines[i + 1 + k] = aligned[k];
        }
        lines[j] = '\t'.repeat (ind) + close;
        i = j;
    }
    return lines.join ('\n');
}

// gofmt aligns each run of consecutive single-line keyed entries on its own (a multi-line entry,
// a blank or a comment line ends the run), so a pass that rewrote one entry of a literal holding
// a nested literal or a func value is realigned run by run; a run with a trailing comment is left alone.
function goGofmtAlignRuns (content: string, aligner: GoCompositeEntryAligner): string {
    const lines = content.split ('\n');
    const live = goTextCodeLineStarts (content);
    const keyed = /^(\t+)"((?:[^"\\]|\\.)*)": +(.*?),( *\/\/.*)?$/;
    const entry = (k: number): RegExpExecArray | null => {
        const m = live[k] ? keyed.exec (lines[k]) : null;
        if (m === null) {
            return null;
        }
        const mask = goTextMaskLiteralsAndComments (m[3]);
        const count = (c: string) => mask.split (c).length;
        const balanced = (count ('(') === count (')')) && (count ('[') === count (']')) && (count ('{') === count ('}'));
        let flat = mask;
        for (let prev = ''; prev !== flat; ) {
            prev = flat;
            flat = flat.replace (/\([^()\[\]{}]*\)|\[[^()\[\]{}]*\]|\{[^()\[\]{}]*\}/g, '');
        }
        return (!balanced || (flat.indexOf (',') >= 0) || (flat.indexOf (':') >= 0)) ? null : m;
    };
    for (let i = 0; i < lines.length; i++) {
        const first = entry (i);
        if (first === null) {
            continue;
        }
        const run: RegExpExecArray[] = [ first ];
        let j = i + 1;
        for (let m = entry (j); (m !== null) && (m[1] === first[1]); m = entry (j)) {
            run.push (m);
            j += 1;
        }
        const commented = run.some ((m) => (m[4] !== undefined) || (goTextMaskLiteralsOnly (m[3]).indexOf ('//') >= 0));
        if (!commented) {
            const aligned = aligner.alignGoCompositeEntries (run.map ((m) => m[1] + '"' + m[2] + '": ' + m[3]));
            if (aligned.length === run.length) {
                for (let k = 0; k < run.length; k++) {
                    lines[i + k] = aligned[k];
                }
            }
        }
        i = j - 1;
    }
    return lines.join ('\n');
}

export function goGofmtLayout (content: string, aligner: GoCompositeEntryAligner = goCompositeKeyAligner ()): string {
    const code = goTextMaskLiteralsAndComments (content).split ('\n');
    const commentFree = goTextMaskLiteralsOnly (content).split ('\n');
    const live = goTextCodeLineStarts (content);
    const lines = content.split ('\n');
    const out: string[] = [];
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (!live[i]) {
            out.push (line);
            continue;
        }
        if (line.trim ().length === 0) {
            if ((out.length > 0) && (out[out.length - 1].trim ().length === 0)) {
                continue;                     // gofmt keeps at most one blank line
            }
            out.push ('');
            continue;
        }
        const expanded = goGofmtExpandBlockLine (line, code[i], commentFree[i]);
        if (expanded !== null) {
            out.push (...expanded);
            continue;
        }
        out.push (line);
    }
    return goGofmtAlignRuns (goGofmtAlignTables (out.join ('\n'), aligner), aligner);
}

function goGofmtLayoutSelfTest (ok: SelfTestOk): void {
    const check = (label: string, actual: string, expected: string) => ok (actual === expected, label + ': ' + JSON.stringify (actual));
    const head = 'package ccxt\n\n// PLEASE DO NOT EDIT THIS FILE, IT IS GENERATED AND WILL BE OVERWRITTEN:\n\n';
    const aligner = goCompositeKeyAligner ();
    const fixed = goGofmtLayout (head + 'func (this *X) f(p any) any {\n\tif p != nil { p = map[string]any{} }\n\treturn p\n}\n', aligner);
    check ('block', fixed, head + 'func (this *X) f(p any) any {\n\tif p != nil {\n\t\tp = map[string]any{}\n\t}\n\treturn p\n}\n');
    check ('blank run', goGofmtLayout ('package ccxt\n\n\nfunc f() {\n}\n', aligner), 'package ccxt\n\nfunc f() {\n}\n');
    check ('table', goGofmtLayout (head + 'func (this *X) f() any {\n\treturn map[string]any{\n\t\t"id": 1,\n\t\t"symbol": "BTC/USDT",\n\t}\n}\n', aligner),
        head + 'func (this *X) f() any {\n\treturn map[string]any{\n\t\t"id":     1,\n\t\t"symbol": "BTC/USDT",\n\t}\n}\n');
    const clean = head + 'func f() int {\n\treturn 1\n}\n';
    check ('idempotent', goGofmtLayout (clean, aligner), clean);
    const run = (a: string, b: string, c: string) => head + 'func (this *X) f() any {\n\treturn map[string]any{\n\t\t' + a + ',\n\t\t' + b + ',\n\t\t"price": func() int {\n\t\t\treturn 1\n\t\t}(),\n\t\t' + c + ',\n\t}\n}\n';
    check ('run before a func value', goGofmtLayout (run ('"won":       won', '"amount": v', '"pnl": p'), aligner), run ('"won":    won', '"amount": v', '"pnl": p'));
    const commented = run ('"a":    1 // x', '"bb": 2', '"c": 3');
    check ('commented run', goGofmtLayout (commented, aligner), commented);
    const slice = (s: string) => 'package x\n\nfunc f() {\n' + s + '}\n';
    check ('slice operand', goGofmtSplicedText (slice ('\tif h[i : i+1] == "0" {\n\t}\n')), slice ('\tif h[i:i+1] == "0" {\n\t}\n'));
    check ('slice statement', goGofmtSplicedText (slice ('\tx := s[0:len(s) - 3]\n')), slice ('\tx := s[0 : len(s)-3]\n'));
}

function overwriteFileAndFolder (path: string, content: string) {
    if (!(fs.existsSync(path))) {
        checkCreateFolder (path);
    }
    // gofmt aligns the trailing `//` comments of adjacent lines through its tabwriter; the
    // printer reproduces that itself (ast-transpiler `alignGoTrailingComments`), and this second
    // pass covers the text assembled here (hand-written emitters and sections concatenated after
    // the transpiled ones). It is a no-op on text that is already aligned. The nil-check collapse
    // runs last so its match sees the canonical spacing.
    content = collapseRedundantNilChecks (formatGoSource (path, normalizeGoFileHeader (alignGoTrailingComments (content))));
    // the collapse rewrites `if (x != nil) && (x != nil) {` into `if (x != nil) {`, and the
    // parens of that form are exactly the ones gofmt's stripParens() takes off a control
    // expression - so the spacing pass runs once more over its output
    // market-row reads run after dropNoOpMapTyped so `MapTyped(this.Market(..))` writes read as rows
    content = goGofmtSplicedText (goGofmtNestedParens (goIsEqualSafeLiteral (goTypedIsEqualNative (goNativeStringHelpers (path, nativeMarketRowReads (goMapTypedOfMapLocal (goOmitChainMapLocals (dropNoOpMapTyped (goSafeBalanceSelfRebind (goSafeListSliceReads (goSafeDictMapReads (goTypedMaplistOmitOfTupleMaps (goOmitDictOfTypedMaps (content))))))))))))));
    content = goTypedGvMapReads (content);
    content = path.endsWith ('.go') ? goHashmapRowReads (content) : content;
    content = goTypedNativeDerefs (path, content);
    content = goTypedStrNativeStringHelpers (path, content);
    content = path.endsWith ('.go') ? goNativeStringAdds (content) : content;  // row reads exist only from here
    content = path.endsWith ('.go') ? goAsyncInt64Value (content) : content;  // typed async int64 value
    content = path.endsWith ('.go') ? goStringSliceIndexPtr (goAsyncStringValue (content, path)) : content;  // typed async string value
    content = path.endsWith ('.go') ? goProvenLocalIsEqual (content) : content;
    content = path.endsWith ('.go') ? goPlainBoxIsEqual (content) : content;
    // struct returns after every retype pass (base ParseTicker is `any` until formatGoSource)
    if (path.endsWith ('.go')) {
        content = goDropRedundantTyped (goStructReturnsPass (content));
        // the base file gains its struct-to-map row wraps only here (parseLedger's itemOrItems is never an array)
        content = (path === BASE_METHODS_FILE) ? goTypedShapeHelpers (content, '') : content;
    }
    // layout last: the passes above splice operands (derefs, natives) after spacing and the
    // comment columns were computed; recompute both from the final text
    if (path.endsWith ('.go')) {
        content = goStdlibStringHelpers (goJoinStringLocals (content));  // string-only []any locals are []string first
        content = goNativeStringAdds (goStringAnyLocals (content));  // string-only `any` locals are strings, their Add chains native
        content = goTypedStrNativeStringHelpers (path, content);  // the Add chains are `+` sums only from here: StartsWith/EndsWith of one go native
        content = goIsEqualBoolMethod (content);  // IsEqual(this.boolMethod(..), true) -> native ==
        content = goSafeStringPtrHoist (content);  // SafeStringPtr(<Go string>) at return / declaration -> &local
        content = goTernaryIifeStatements (content);  // typed statement-level ternary literals -> if/else
        content = goTernaryIifeOperands (content);  // typed ternary literals inside a statement -> hoisted if/else
        content = goGuardIifeOperands (content);  // nil-guarded map-membership / substring literals -> typed locals
        content = goTernaryAnyTyped (content);  // `func() any` ternaries whose arms share one Go type -> typed if/else
        content = goTernaryAnyAssign (content);  // `x = func() any` ternaries of one arm type into an existing box -> if/else
        // runs after the spacing pass: its line-local lexer misreads a `}(args) + x` continuation
        content = alignGoTrailingComments (goGofmtBinarySpacing (content));
    }
    content = path.endsWith ('.go') ? goTypedRecvLocals (content) : content;  // after every pass keyed on `x := rN.Value`
    content = path.endsWith ('.go') ? goTypedNilFoldLocals (content) : content;
    content = path.endsWith ('.go') ? goTypedEndpointNilLocals (content) : content;
    content = path.endsWith ('.go') ? goTypedEndpointRawLocals (content) : content;
    content = path.endsWith ('.go') ? goLateNativeInOp (content) : content;  // receivers typed by the three passes above
    content = path.endsWith ('.go') ? goNativeKeysAndRemove (content) : content;  // ObjectKeys of the late-typed map locals
    content = path.endsWith ('.go') ? goTypedLenNative (content) : content;  // list locals typed only by the late passes
    // gofmt's block/blank/table layout, once, on the text every pass above has finished
    content = path.endsWith ('.go') ? goGofmtLayout (content, goCompositeKeyAligner ()) : content;
    if (path.endsWith ('.go')) {
        // a `future` local holding client.reusableFuture () is a *Future, but its await is printed as a
        // channel receive when the awaited value is returned as is (e.g. a balance or an order book)
        content = content.replace (/(\br\d+) := <-future\.\(<-chan ccxt\.AsyncResult\[any\]\)/g, '$1 := <-future.(*ccxt.Future).Await()');
    }
    overwriteFile (path, content);
}

// `x := rN.Value` of a receive whose element type the go-chan3 table or a typed endpoint stub fixes:
// declare x with that type (the same static type `:=` inferred). Unproven receives keep `:=`.
const GO_TYPED_RECV_LOCAL_TYPES = new Set ([ 'map[string]any', '[]any', '*string', 'string', 'bool', '*int64', 'int64' ]);
function goTypedRecvLocals (content: string): string {
    if (!/\n\t+\w+ := r\d*\.Value\n/.test (content)) {
        return content;
    }
    const masked = goChanMask (content);
    const table = goChan3Table ();
    const re = /\n(\t+)(\w+) := (r\d*)\.Value(?=\n)/g;
    const edits: Edit[] = [];
    for (let m = re.exec (masked); m !== null; m = re.exec (masked)) {
        const [ fs0, fe0 ] = goChan3Func (masked, m.index + 1);
        const fn = masked.substring (fs0, fe0);
        const r = m[3];
        const binds = fn.match (new RegExp ('\\n\\t+' + r + ' := <-[^\\n]*', 'g')) || [];
        const writes = fn.match (new RegExp ('(?<![\\w.])' + r + '(?:\\s*,\\s*\\w+)*\\s*:?=(?!=)', 'g')) || [];
        if ((binds.length !== 1) || (writes.length !== 1)) {
            continue;
        }
        const recv = goChan3EnclosingReceiver (masked, m.index + 1);
        const async = /:= <-this\.(?:\w+\.)?(\w+)Async\(/.exec (binds[0]);
        const stub = /:= <-this\.(\w+)\(/.exec (binds[0]);
        let type: string | undefined = undefined;
        if (async !== null) {
            const raw = goChan3LookupRaw (table, recv, async[1]);
            type = ((raw === undefined) || raw.endsWith ('?')) ? undefined : raw;
        } else if ((stub !== null) && (recv !== undefined)) {
            const s = goChan3ReceiverStubs ().get (recv + '.' + stub[1]);
            type = ((s !== undefined) && (s[0] === 'E')) ? s.substring (2) : undefined;
        }
        if ((type === undefined) || !GO_TYPED_RECV_LOCAL_TYPES.has (type)) {
            continue;
        }
        const start = m.index + 1 + m[1].length;
        edits.push ({ start, 'end': start + m[2].length + 4 + r.length + 6, 'text': 'var ' + m[2] + ' ' + type + ' = ' + r + '.Value' });
    }
    return edits.length ? goChan3Splice (content, edits) : content;
}

// `var x any = nil; if rN.Value != nil { x = <rN.Value | XsToList(rN.Value)> }` of a map/list receive: a nil map/slice
// reads like the untyped nil through every use admitted here (Safe* readers, GetValue, GetArrayLength, native nil test,
// the `[]any` slot of ParseOpenInterests),
// so x takes the receive's type and the guard goes.
const GO_NIL_FOLD_READERS = /^(?:this\.(?:Safe(?:String|Integer|Number|Bool|Float|Dict|List|Value|Timestamp)\w*|IsEmpty)|(?:ccxt\.)?(?:SafeMapTyped|SafeListTyped\w*|GetValue|GetArrayLength)|this\.ParseOpenInterests)\($/;
function goTypedNilFoldLocals (content: string): string {
    if (!/\n\t+var \w+ any = nil\n\t+if r\d*\.Value != nil \{\n/.test (content)) {
        return content;
    }
    const masked = goChanMask (content);
    const table = goChan3Table ();
    const re = /\n(\t+)var (\w+) any = nil\n\1if (r\d*)\.Value != nil \{\n\1\t\2 = ((?:ccxt\.)?\w+ToList\(\3\.Value\)|\3\.Value)\n\1\}(?=\n)/g;
    const edits: Edit[] = [];
    for (let m = re.exec (masked); m !== null; m = re.exec (masked)) {
        const [ ind, name, r, value ] = [ m[1], m[2], m[3], m[4] ];
        const [ fs0, fe0 ] = goChan3Func (masked, m.index + 1);
        const fn = masked.substring (fs0, fe0);
        const binds = fn.match (new RegExp ('\\n\\t+' + r + ' := <-this\\.(?:\\w+\\.)?(\\w+)Async\\(', 'g')) || [];
        const rWrites = fn.match (new RegExp ('(?<![\\w.])' + r + '(?:\\s*,\\s*\\w+)*\\s*:?=(?!=)', 'g')) || [];
        if ((binds.length !== 1) || (rWrites.length !== 1)) {
            continue;
        }
        let type: string | undefined = '[]any';
        if (value === r + '.Value') {
            const raw = goChan3LookupRaw (table, goChan3EnclosingReceiver (masked, m.index + 1), /(\w+)Async\($/.exec (binds[0])[1]);
            type = ((raw === 'map[string]any') || (raw === '[]any')) ? raw : undefined;
        } else if (!/ToList\(/.test (value) || /OHLCVToList\(/.test (value) || /^(?:ccxt\.)?ToList\(/.test (value)) {
            type = undefined;
        }
        if (type === undefined) {
            continue;
        }
        const offset = m.index - fs0;
        const rest = fn.substring (0, offset) + fn.substring (offset + m[0].length);
        const use = new RegExp ('(?<![\\w.&])' + name + '\\b', 'g');
        let safe = true;
        for (let u = use.exec (rest); safe && (u !== null); u = use.exec (rest)) {
            const before = rest.substring (Math.max (0, u.index - 60), u.index);
            const after = rest.substring (u.index + name.length, u.index + name.length + 8);
            const reader = /((?:this\.|ccxt\.)?\w+\()$/.exec (before);
            const nilTest = /^ [!=]= nil\b/.test (after) && !/IsEqual\($/.test (before);
            safe = nilTest || ((reader !== null) && GO_NIL_FOLD_READERS.test (reader[1]) && /^[,)]/.test (after));
        }
        if (!safe || new RegExp ('&' + name + '\\b|var ' + name + '\\b|' + name + '\\s*[-+*/]?:?=(?!=)').test (rest)) {
            continue;
        }
        const start = m.index + 1;
        edits.push ({ start, 'end': m.index + m[0].length, 'text': ind + 'var ' + name + ' ' + type + ' = ' + content.substring (m.index + m[0].lastIndexOf ('= ') + 2, m.index + m[0].lastIndexOf ('\n')) });
    }
    return edits.length ? goChan3Splice (content, edits) : content;
}

// `var x any = nil` whose every write is `x = rN.Raw` of one typed endpoint stub (map/list T): x is T and the writes read
// Value. Uses: nil tests, nil-tolerant reader first args, or anything after a same-block `if x == nil { panic(` guard.
function goTypedEndpointNilLocals (content: string): string {
    if (!/\n\t+\w+ = r\d*\.Raw\n/.test (content)) {
        return content;
    }
    const masked = goChanMask (content);
    const re = /\n(\t+)var (\w+) any = nil(?=\n)/g;
    const edits: Edit[] = [];
    for (let m = re.exec (masked); m !== null; m = re.exec (masked)) {
        const [ ind, name ] = [ m[1], m[2] ];
        const [ fs0, fe0 ] = goChan3Func (masked, m.index + 1);
        const fn = masked.substring (fs0, fe0);
        const recv = goChan3EnclosingReceiver (masked, m.index + 1);
        const writes = [ ...fn.matchAll (new RegExp ('\\n\\t+' + name + ' = ([^\\n]*)', 'g')) ];
        if ((recv === undefined) || !writes.length || ((fn.match (new RegExp ('\\bvar ' + name + '\\b', 'g')) || []).length !== 1)) {
            continue;
        }
        const types = new Set<string | undefined> ();
        for (const w of writes) {
            const r = /^(r\d*)\.Raw$/.exec (w[1]);
            const binds = (r === null) ? [] : (fn.match (new RegExp ('\\n\\t+' + r[1] + ' := <-this\\.(\\w+)\\(', 'g')) || []);
            const rWrites = (r === null) ? [] : (fn.match (new RegExp ('(?<![\\w.])' + r[1] + '(?:\\s*,\\s*\\w+)*\\s*:?=(?!=)', 'g')) || []);
            const s = ((binds.length === 1) && (rWrites.length === 1)) ? goChan3ReceiverStubs ().get (recv + '.' + /<-this\.(\w+)\($/.exec (binds[0])[1]) : undefined;
            types.add (((s !== undefined) && (s[0] === 'E')) ? s.substring (2) : undefined);
        }
        const type = (types.size === 1) ? [ ...types ][0] : undefined;
        if ((type !== 'map[string]any') && (type !== '[]any')) {
            continue;
        }
        const declEnd = m.index + m[0].length - fs0;
        const guard = new RegExp ('\\n' + ind + 'if ' + name + ' == nil \\{\\n' + ind + '\\tpanic\\(').exec (fn.substring (declEnd));
        const guardAt = (guard === null) ? -1 : declEnd + guard.index;
        const lastWrite = writes[writes.length - 1].index;
        const guarded = (guardAt > lastWrite) && !fn.substring (declEnd, guardAt).split ('\n').some ((l) => (l.length > 0) && !l.startsWith (ind));
        const use = new RegExp ('(?<![\\w.&])' + name + '\\b', 'g');
        let safe = true;
        for (let u = use.exec (fn); safe && (u !== null); u = use.exec (fn)) {
            const lead = fn.substring (fn.lastIndexOf ('\n', u.index) + 1, u.index);
            const before = fn.substring (Math.max (0, u.index - 60), u.index);
            const after = fn.substring (u.index + name.length, u.index + name.length + 8);
            if ((u.index === m.index + 1 + ind.length + 4 - fs0) || (/^\t+$/.test (lead) && / = r\d*\.Raw\n/.test (fn.substring (u.index + name.length, fn.indexOf ('\n', u.index) + 1)))) {
                continue;
            }
            const reader = /((?:this\.|ccxt\.)?\w+\()$/.exec (before);
            const nilTest = /^ [!=]= nil\b/.test (after) && !/IsEqual\($/.test (before);
            const handOff = guarded && (u.index > guardAt) && /^[,)]/.test (after) && (reader !== null || /, $/.test (before));
            safe = nilTest || handOff || ((reader !== null) && (GO_NIL_FOLD_READERS.test (reader[1]) || GO_ENDPOINT_KEY_READERS.test (reader[1])) && /^[,)]/.test (after));
        }
        if (!safe || new RegExp ('&' + name + '\\b|' + name + '\\s*[-+*/]=').test (fn)) {
            continue;
        }
        edits.push ({ 'start': m.index + 1 + ind.length, 'end': m.index + m[0].length, 'text': 'var ' + name + ' ' + type + ' = nil' });
        for (const w of writes) {
            const at = fs0 + w.index + w[0].length - 3;
            edits.push ({ 'start': at, 'end': at + 3, 'text': 'Value' });
        }
    }
    return edits.length ? goChan3Splice (content, edits) : content;
}

// InOp / ObjectKeys / GetValue answer false / nil / nil for a nil map exactly as for a non-map box
const GO_ENDPOINT_KEY_READERS = /^(?:ccxt\.)?(?:InOp|ObjectKeys|GetValue)\($/;
// `x := rN.Raw` of a map[string]any endpoint read only by first-argument readers (with >= 1 InOp/ObjectKeys/GetValue) and
// nil tests: x is `var x map[string]any = rN.Value` (MapTyped of the same Raw: a map passes through, else nil)
function goTypedEndpointRawLocals (content: string): string {
    if (!/\n\t+\w+ := r\d*\.Raw\n/.test (content)) {
        return content;
    }
    const masked = goChanMask (content);
    const re = /\n(\t+)(\w+) := (r\d*)\.Raw(?=\n)/g;
    const edits: Edit[] = [];
    for (let m = re.exec (masked); m !== null; m = re.exec (masked)) {
        const [ ind, name, r ] = [ m[1], m[2], m[3] ];
        const [ fs0, fe0 ] = goChan3Func (masked, m.index + 1);
        const fn = masked.substring (fs0, fe0);
        const recv = goChan3EnclosingReceiver (masked, m.index + 1);
        const binds = fn.match (new RegExp ('\\n\\t+' + r + ' := <-this\\.(\\w+)\\(', 'g')) || [];
        const rWrites = fn.match (new RegExp ('(?<![\\w.])' + r + '(?:\\s*,\\s*\\w+)*\\s*:?=(?!=)', 'g')) || [];
        const s = ((recv === undefined) || (binds.length !== 1) || (rWrites.length !== 1)) ? undefined : goChan3ReceiverStubs ().get (recv + '.' + /<-this\.(\w+)\($/.exec (binds[0])[1]);
        const decls = fn.match (new RegExp ('(?<![\\w.])' + name + '\\s*(?:,[^=\\n]*)?:?=(?!=)|\\bvar ' + name + '\\b|,\\s*' + name + '\\s*:?=(?!=)|&' + name + '\\b', 'g')) || [];
        if ((s !== 'E:map[string]any') || (decls.length !== 1)) {
            continue;
        }
        const declAt = m.index + 1 - fs0;
        const use = new RegExp ('(?<![\\w.&])' + name + '\\b', 'g');
        let [ safe, keyed ] = [ true, false ];
        for (let u = use.exec (fn); safe && (u !== null); u = use.exec (fn)) {
            if (u.index === declAt + ind.length) {
                continue;
            }
            const before = fn.substring (Math.max (0, u.index - 60), u.index);
            const after = fn.substring (u.index + name.length, u.index + name.length + 8);
            const reader = /((?:this\.|ccxt\.)?\w+\()$/.exec (before);
            const key = (reader !== null) && GO_ENDPOINT_KEY_READERS.test (reader[1]) && /^[,)]/.test (after);
            keyed = keyed || key;
            safe = key || (/^ [!=]= nil\b/.test (after) && !/IsEqual\($/.test (before)) || ((reader !== null) && GO_NIL_FOLD_READERS.test (reader[1]) && /^[,)]/.test (after));
        }
        if (safe && keyed) {
            const start = m.index + 1 + ind.length;
            edits.push ({ start, 'end': start + name.length + 4 + r.length + 4, 'text': 'var ' + name + ' map[string]any = ' + r + '.Value' });
        }
    }
    return edits.length ? goChan3Splice (content, edits) : content;
}

function goTypedEndpointNilLocalsCheck (ok: SelfTestOk): void {
    const stubs = new Map ([ [ 'Zz.PubGetM', 'E:map[string]any' ], [ 'Zz.PubGetL', 'E:[]any' ] ]);
    const saved = GO_CHAN3_RECV_STUBS;
    goChan3SetReceiverStubsForTest (stubs);
    const recv = (r: string, call: string) => '\t\t' + r + ' := <-this.' + call + '(p)\n\t\tif ' + r + '.Err != nil {\n\t\t\tpanic(' + r + '.Err)\n\t\t}\n';
    const fn = (x: string, c1: string, c2: string, tail: string) => 'func (this *Zz) f' + x + '(p any) any {\n\tvar ' + x + ' any = nil\n\tif p == nil {\n' + recv ('r', c1) + '\t\t' + x + ' = r.Raw\n\t} else {\n' + recv ('r1', c2) + '\t\t' + x + ' = r1.Raw\n\t}\n' + tail + '}\n';
    const src = 'package ccxt\n\n' + fn ('a', 'PubGetM', 'PubGetM', '\tif a == nil {\n\t\tpanic(NullResponse(\"x\"))\n\t}\n\treturn this.ParseOrder(a)\n') +
        fn ('b', 'PubGetM', 'PubGetL', '\treturn this.SafeString(b, \"k\")\n') + fn ('c', 'PubGetL', 'PubGetL', '\treturn this.ParseOrders(c)\n') + fn ('d', 'PubGetL', 'PubGetL', '\treturn GetArrayLength(d)\n');
    const out = goTypedEndpointNilLocals (src);
    goChan3SetReceiverStubsForTest (saved);
    ok (out.includes ('\tvar a map[string]any = nil\n') && out.includes ('\t\ta = r1.Value\n'), 'guarded map endpoint local typed: ' + out);
    ok (out.includes ('\tvar b any = nil\n') && out.includes ('\t\tb = r1.Raw\n'), 'mixed stubs kept: ' + out);
    ok (out.includes ('\tvar c any = nil\n'), 'unguarded hand-off kept: ' + out);
    ok (out.includes ('\tvar d []any = nil\n') && out.includes ('\t\td = r.Value\n'), 'reader-only list local typed: ' + out);
    goChan3SetReceiverStubsForTest (stubs);
    const one = (x: string, tail: string) => 'func (this *Zz) g' + x + '(p any) any {\n' + recv ('r', 'PubGetM').replace (/\t\t/g, '\t') + '\t' + x + ' := r.Raw\n' + tail + '}\n';
    const raw = goTypedEndpointRawLocals ('package ccxt\n\n' + one ('e', '\tif InOp(e, \"k\") {\n\t\treturn this.SafeString(e, \"k\")\n\t}\n\treturn nil\n') + one ('g', '\tif InOp(g, \"k\") {\n\t\treturn this.Json(g)\n\t}\n\treturn nil\n') + one ('h', '\treturn this.SafeString(h, \"k\")\n'));
    const keys = goTypedEndpointNilLocals ('package ccxt\n\n' + fn ('q', 'PubGetM', 'PubGetM', '\tvar ks []string = ObjectKeys(q)\n\treturn ks\n'));
    goChan3SetReceiverStubsForTest (saved);
    ok (raw.includes ('\tvar e map[string]any = r.Value\n') && raw.includes ('\tg := r.Raw\n') && raw.includes ('\th := r.Raw\n'), 'raw map endpoint local typed only with a keyed read and no hand-off: ' + raw);
    ok (keys.includes ('\tvar q map[string]any = nil\n'), 'ObjectKeys-read map endpoint local typed: ' + keys);
}

function goTypedNilFoldLocalsCheck (ok: SelfTestOk): void {
    const fold = (r: string, call: string, x: string, v: string) => '\t' + r + ' := <-this.' + call + '\n\tif ' + r + '.Err != nil {\n\t\tpanic(' + r + '.Err)\n\t}\n\tvar ' + x + ' any = nil\n\tif ' + r + '.Value != nil {\n\t\t' + x + ' = ' + v + '\n\t}\n';
    const src = 'package ccxt\n\nfunc (this *Zz) f() any {\n' + fold ('r', 'HandleUTAAndParamsAsync(nil)', 'a', 'r.Value') + fold ('r1', 'FetchOrdersAsync()', 'b', 'OrdersToList(r1.Value)') +
        fold ('r2', 'NoSuchThingAsync()', 'c', 'r2.Value') + fold ('r3', 'FetchOrdersAsync()', 'd', 'OrdersToList(r3.Value)') +
        '\tx := GetArrayLength(b) + len(this.SafeString(a, "k"))\n\treturn []any{x, c, d}\n}\n';
    const out = goTypedNilFoldLocals (src);
    ok (out.includes ('\tvar a []any = r.Value\n'), 'tabled list fold typed: ' + out);
    ok (out.includes ('\tvar b []any = OrdersToList(r1.Value)\n'), 'ToList fold typed: ' + out);
    ok (out.includes ('\tvar c any = nil\n'), 'untabled fold kept: ' + out);
    ok (out.includes ('\tvar d any = nil\n'), 'fold handed on as a value kept: ' + out);
}

function goLateNativeInOpCheck (ok: SelfTestOk): void {
    const f = (body: string) => goLateNativeInOp ('func (this *X) f(k any) any {\n\tvar m map[string]any = nil\n\tr1 := <-this.GAsync()\n\tm = r1.Value\n' + body + '\treturn nil\n}\n');
    ok (f ('\tif InOp(m, "a") {\n\t}\n').includes ('if _, ok := m["a"]; ok {'), 'late inop: typed receive map, literal key');
    ok (f ('\tif InOp(m, k) {\n\t}\n').includes ('InOp(m, k)'), 'late inop: any key keeps the helper');
    const a = (body: string) => goLateNativeInOp ('func (this *X) f(p any) any {\n\tt0, t1 := this.HandleParamString(p, "tag")\n\tq := t1\n' + body + '\treturn t0\n}\n');
    ok (a ('\tif InOp(q, "key") {\n\t}\n').includes ('if _, ok := q["key"]; ok {'), 'late inop: alias of a params slot');
    ok (a ('\tq = nil\n\tif InOp(q, "key") {\n\t}\n').includes ('InOp(q, "key")'), 'late inop: rewritten alias keeps the helper');
}

function goTypedRecvLocalsCheck (ok: SelfTestOk): void {
    const recv = (r: string, call: string) => '\t' + r + ' := <-this.' + call + '\n\tif ' + r + '.Err != nil {\n\t\tpanic(' + r + '.Err)\n\t}\n';
    const src = 'package ccxt\n\nfunc (this *Zz) f() any {\n' + recv ('r', 'IsUTAEnabledAsync()') + '\tu := r.Value\n' +
        recv ('r1', 'NoSuchThingAsync()') + '\tv := r1.Value\n' + recv ('r2', 'HandleUTAAndParamsAsync(nil)') + '\th := r2.Value\n\treturn []any{u, v, h}\n}\n';
    const out = goTypedRecvLocals (src);
    ok (out.includes ('\tvar u bool = r.Value\n'), 'tabled bool receive: ' + out);
    ok (out.includes ('\tv := r1.Value\n'), 'untabled receive kept: ' + out);
    ok (out.includes ('\tvar h []any = r2.Value\n'), 'tabled list receive: ' + out);
}

// Methods in CCXT_GO_BOOL_METHOD_NAMES are `: boolean` in ts/src and return a Go bool on every path, so their declared
// `any` return is retagged `bool`. Signature half of the rule in build/go-local-types.js, which types
// `var x any = this.M(...)` as `bool` off the same list, so the two cannot drift.
function coerceGoBoolMethodReturns (content: string, names: string[]): string {
    for (const name of names) {
        const coerceRegex = new RegExp ('(func\\s+\\(this\\s+\\*\\w+\\)\\s+' + name + '\\([^)]*\\))\\s+any(\\s+\\{)', 'g');
        // the replacement spells the single space before `{` itself, so a padded
        // signature (`) any  {`) can never survive the coercion as `) bool  {`
        content = content.replace (coerceRegex, '$1 bool {');
    }
    return content;
}

function capitalize(s: string) {
    return s.charAt(0).toUpperCase() + s.slice(1);
}

// The indentation of the line that the match starting at `offset` sits on: emitters that split
// one expression into several Go statements indent every emitted line with it.
function statementIndent (whole: string, offset: number): string {
    const lineStart = whole.lastIndexOf ('\n', offset - 1) + 1;
    const prefix = whole.substring (lineStart, offset);
    const match = prefix.match (/^[ \t]*/);
    return match ? match[0] : '';
}

// on windows the pathname keeps a leading '/' (/C:Users/user/Desktop/), which is invalid
if (platform === 'win32') {
    if (__dirname[0] === '/') {
        __dirname = __dirname.substring(1);
    }
}

